class RateLimiter:
    def __init__(self, min_interval: float = 1.0) -> None:
        self.min_interval = min_interval
        self.last_request_time: Dict[str, float] = {}
        self.lock = threading.Lock()

    def wait_if_needed(self, key: str = "default") -> None:
        with self.lock:
            current_time = time.time()
            if key in self.last_request_time:
                elapsed = current_time - self.last_request_time[key]
                if elapsed < self.min_interval:
                    wait_time = self.min_interval - elapsed
                    time.sleep(wait_time)
            self.last_request_time[key] = time.time()


xai_rate_limiter = RateLimiter(min_interval=0.5)


def validate_api_key(key: str, service: str) -> bool:
    if not key:
        logger.error(f"{service} API key is required but not configured.")
        raise ValueError(f"{service} API key is required but not configured.")
    return True


def retry_on_rate_limit(max_retries: int = 10):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            last_error: Exception = None
            for attempt in range(max_retries):
                try:
                    return func(*args, **kwargs)
                except requests.exceptions.HTTPError as e:
                    last_error = e
                    status = e.response.status_code if e.response is not None else None
                    if status == 429 and attempt < max_retries - 1:
                        base_wait = min(2**attempt, 60)
                        wait_time = base_wait + random.uniform(0.0, 5.0)
                        logger.warning(
                            f"Rate limit hit for {func.__name__}, waiting {wait_time:.2f}s before retry {attempt + 1}/{max_retries}"
                        )
                        time.sleep(wait_time)
                        continue
                    elif status == 429:
                        logger.error(f"Rate limit exceeded after {max_retries} retries for {func.__name__}")
                        raise
                    raise
                except requests.exceptions.RequestException as e:
                    last_error = e
                    if attempt < max_retries - 1:
                        wait_time = (2**attempt) + random.uniform(0.0, 1.0)
                        logger.warning(
                            f"Request error for {func.__name__}, waiting {wait_time:.2f}s before retry {attempt + 1}/{max_retries}"
                        )
                        time.sleep(wait_time)
                        continue
                    raise Exception(f"Max retries exceeded for {func.__name__}") from last_error
            raise Exception(f"Max retries exceeded for {func.__name__}") from last_error

        return wrapper

    return decorator


class CerebrasAgent:
    def __init__(self, model: str = "gpt-oss-120b") -> None:
        self.model = model
        self.max_completion_tokens = CEREBRAS_MAX_TOKENS
        try:
            from cerebras.cloud.sdk import Cerebras

            self.client = Cerebras(api_key=CEREBRAS_API_KEY)
        except ImportError:
            logger.error("Cerebras SDK not available, falling back to HTTP requests")
            self.client = None
            self.headers = {
                "Authorization": f"Bearer {CEREBRAS_API_KEY}",
                "Content-Type": "application/json",
            }

    @retry_on_rate_limit()
    def chat(
        self,
        messages: List[Dict[str, Any]],
        temperature: float = 0.07,
        max_tokens: int = None,
        timeout: int = 180,
    ) -> Dict[str, Any]:
        validate_api_key(CEREBRAS_API_KEY, "Cerebras")
        effective_max = int(max_tokens) if max_tokens is not None else int(self.max_completion_tokens)
        if self.client is not None:
            stream = self.client.chat.completions.create(
                messages=messages,
                model=self.model,
                stream=False,
                max_completion_tokens=effective_max,
                temperature=float(temperature),
                top_p=0.03,
                reasoning_effort="low" if self.model == "gpt-oss-120b" else None,
            )
            content = stream.choices[0].message.content
            return {"choices": [{"message": {"content": content, "role": "assistant"}}]}
        url = f"{CEREBRAS_BASE_URL}/chat/completions"
        payload: Dict[str, Any] = {
            "model": self.model,
            "messages": messages,
            "temperature": float(temperature),
            "max_completion_tokens": effective_max,
            "top_p": 0.03,
        }
        if self.model == "gpt-oss-120b":
            payload["reasoning_effort"] = "low"
        response = requests.post(url, headers=self.headers, json=payload, timeout=timeout)
        response.raise_for_status()
        return response.json()


