    ) -> Dict[str, Any]:
        validate_api_key(XAI_API_KEY, "xAI")
        xai_rate_limiter.wait_if_needed("grok4-fast-reasoning")
        url = f"{XAI_BASE_URL}/chat/completions"
        effective_max = int(max_tokens) if max_tokens is not None else min(XAI_MAX_TOKENS, 2000000)
        payload = {
            "model": self.model,
            "messages": messages,
            "temperature": float(temperature),
            "max_tokens": effective_max,
        }
        response = requests.post(url, headers=self.headers, json=payload, timeout=timeout)
        response.raise_for_status()
        return response.json()


