class ExaResearchAgent:
    def __init__(self, use_kernel_browser: bool = False) -> None:
        self.exa = exa_client
        if not self.exa:
            raise ValueError("Exa client is not available")
        self.use_kernel_browser = bool(use_kernel_browser and kernel_client is not None)
        self.kernel_browser_session = None

    @retry_on_rate_limit()
    def search(
        self,
        query: str,
        num_results: int = 100,
        search_type: str = "auto",
        **kwargs: Any,
    ) -> Dict[str, Any]:
        validate_api_key(EXA_API_KEY, "Exa")
        try:
            result = self.exa.search(
                query=query,
                num_results=min(int(num_results), EXA_NUM_RESULTS_MAX),
                type=search_type.lower() if search_type else "auto",
                contents=False,
                **kwargs,
            )
            return {
                "results": [
                    {
                        "id": r.id,
                        "url": getattr(r, "url", ""),
                        "title": getattr(r, "title", ""),
                        "score": getattr(r, "score", None),
                        "published_date": getattr(r, "published_date", None),
                        "author": getattr(r, "author", None),
                    }
                    for r in result.results
                ]
            }
        except Exception as e:
            logger.error(f"Exa search error: {str(e)}")
            raise

    @retry_on_rate_limit()
    def get_contents(self, ids: List[str], text: Any = True, **kwargs: Any) -> Dict[str, Any]:
        validate_api_key(EXA_API_KEY, "Exa")
        try:
            if isinstance(ids, str):
                ids = [ids]
            if not ids:
                return {"contents": {}}
            result = self.exa.get_contents(ids, text=text, **kwargs)
            contents_dict: Dict[str, Dict[str, Any]] = {}
            for r in result.results:
                contents_dict[r.id] = {
                    "url": getattr(r, "url", ""),
                    "title": getattr(r, "title", ""),
                    "id": r.id,
                    "text": getattr(r, "text", "") if hasattr(r, "text") and getattr(r, "text", "") else "",
                }
            return {"contents": contents_dict}
        except Exception as e:
            logger.error(f"Exa get_contents error: {str(e)}")
            raise


class SubAgent:
    def __init__(self, agent_id: str, specialty: str, agent_model: Any, exa: ExaResearchAgent) -> None:
        self.agent_id = agent_id
        self.specialty = specialty
        self.agent_model = agent_model
        self.exa = exa
        self.groq_kimi = GroqKimiAgent()
        self.sources_found: List[Dict[str, Any]] = []
        self.content_gathered: List[Dict[str, Any]] = []
        self.status: str = "initializing"
        self.progress: int = 0

    def research(self, task_description: str, max_sources: int = 500) -> Dict[str, Any]:
        self.status = "planning_searches"
        self.progress = 10
        planning_prompt = (
            "Feladat: "
            + task_description
            + "\nSpecialty: "
            + self.specialty
            + "\n\nGenerálj keresési lekérdezéseket ehhez a kutatási feladathoz.\n"
            + "Készíts minél több (akár 15-20) változatos keresési lekérdezést, amelyek fedik le a témát.\n"
            + 'Válaszolj JSON formátumban: {"queries": ["lekérdezés1", "lekérdezés2", ...]}'
        )
        try:
            plan_response = self.agent_model.chat(
                [
                    {
                        "role": "system",
                        "content": "Te "
                        + self.specialty
                        + " területén kutatsz. Generálj sokrétű keresési lekérdezéseket.",
                    },
                    {"role": "user", "content": planning_prompt},
                ],
                temperature=0.2,
                max_tokens=4096,
            )
            plan_data = self._extract_json(plan_response["choices"][0]["message"]["content"])
            search_queries = plan_data.get("queries", [task_description])
            if not isinstance(search_queries, list):
                search_queries = [task_description]
            search_queries = search_queries[:20]
        except Exception as e:
            logger.error(f"Query planning error: {e}")
            search_queries = [task_description, f"{self.specialty}: {task_description}"]
        self.status = "searching"
        self.progress = 20
        all_results: List[Dict[str, Any]] = []
        seen_ids: Set[str] = set()
        max_sources = int(max_sources) if max_sources is not None else 500
        if max_sources <= 0:
            max_sources = 1
        with concurrent.futures.ThreadPoolExecutor(max_workers=5) as executor:
            futures = [
                executor.submit(self._execute_search, query=q, num_results=100) for q in search_queries
            ]
            total_queries = len(futures)
            completed = 0
            for future in concurrent.futures.as_completed(futures):
                try:
                    results = future.result()
                    for res in results:
                        source_id = res.get("id") or res.get("url")
                        if source_id and source_id not in seen_ids and len(all_results) < max_sources:
                            seen_ids.add(source_id)
                            all_results.append(res)
                except Exception as e:
                    logger.error(f"SubAgent {self.agent_id} search error: {e}")
                completed += 1
                if total_queries > 0:
                    self.progress = 20 + int((completed / total_queries) * 40)
        self.progress = 60
        self.sources_found = all_results
        self.status = "analyzing"
        self.progress = 70
        batch_size = 50
        for i in range(0, len(all_results), batch_size):
            batch_ids = [r["id"] for r in all_results[i : i + batch_size] if "id" in r]
            try:
                if batch_ids:
                    contents = self.exa.get_contents(batch_ids, text=True)
                    self.content_gathered.extend(list(contents.get("contents", {}).values()))
            except Exception as e:
                logger.error(f"SubAgent {self.agent_id} content error: {e}")
            if len(all_results) > 0:
                self.progress = 70 + int((i / len(all_results)) * 20)
        if self.content_gathered:
            self.status = "fact_checking"
            self.progress = 90
            try:
                fact_check_prompt = (
                    "Specialty: "
                    + self.specialty
                    + "\nTask: "
                    + task_description
                    + "\n\nAz alábbi "
                    + str(len(self.content_gathered))
                    + " forrás alapján végezz tényalapú ellenőrzést:\n"
                    + "- NE használj placeholder vagy mock adatokat\n"
                    + "- NE találj ki információt\n"
                    + "- Csak a források konkrét adatait használd\n"
                    + "- Jelöld meg a bizonytalan információkat\n\n"
                    + "Források alapján készíts rövid, tényszerű összefoglalót."
                )
                fact_check_messages = [
                    {
                        "role": "system",
                        "content": "Te egy precíz, tényalapú kutató vagy. Tilos hazudni, kitalálni vagy placeholder adatokat használni.",
                    },
                    {"role": "user", "content": fact_check_prompt},
                ]
                verification = self.groq_kimi.chat(
                    fact_check_messages,
                    temperature=0.05,
                    max_tokens=8192,
                )
                verification_content = verification["choices"][0]["message"]["content"]
                self.content_gathered.append(
                    {
                        "title": "[VERIFIED] " + self.specialty + " - Fact-checked Summary",
                        "text": verification_content,
                        "url": "",
                        "verified": True,
                    }
                )
                logger.info(f"SubAgent {self.agent_id} fact-checking completed")
            except Exception as e:
                logger.error(f"SubAgent {self.agent_id} fact-checking error: {e}")
            self.progress = 95
        self.status = "completed"
        self.progress = 100
        return {
            "agent_id": self.agent_id,
            "specialty": self.specialty,
            "sources_count": len(self.sources_found),
            "content_count": len(self.content_gathered),
            "sources": self.sources_found,
            "contents": self.content_gathered,
        }

    def _execute_search(self, query: str, num_results: int = 100) -> List[Dict[str, Any]]:
        try:
            result = self.exa.search(query=query, num_results=num_results, search_type="auto")
            return result.get("results", [])
        except Exception as e:
            logger.error(f"Search error for query '{query}': {e}")
            return []

    def _extract_json(self, text: str) -> Dict[str, Any]:
        text = (text or "").strip()
        try:
            return json.loads(text)
        except json.JSONDecodeError:
            pass
        json_match = re.search(r"``````", text, re.DOTALL)
        if json_match:
            try:
                return json.loads(json_match.group(1))
            except Exception:
                pass
        brace_count = 0
        start = -1
        for i, ch in enumerate(text):
            if ch == "{":
                if brace_count == 0:
                    start = i
                brace_count += 1
            elif ch == "}":
                brace_count -= 1
                if brace_count == 0 and start != -1:
                    try:
                        return json.loads(text[start : i + 1])
                    except Exception:
                        start = -1
        return {}


class AdvancedResearchOrchestrator:
    def __init__(self) -> None:
        self.main_grok = Grok4Agent()
        self.middle_grok = Grok4FastReasoningAgent()
        self.exa = ExaResearchAgent()
        self.kimi = GroqKimiAgent()
        self.glm = GLM4Agent()
        self.gpt_oss = CerebrasAgent(model="gpt-oss-120b")
        self.grok_fast = Grok4FastAgent()

    def execute_deep_research(self, task_id: str, user_query: str, options: Dict[str, Any] = None) -> Dict[str, Any]:
        max_hours = options.get("max_hours", MAX_RESEARCH_HOURS) if options else MAX_RESEARCH_HOURS
        max_sources = options.get("max_sources", MAX_SOURCES_PER_SUBAGENT * MAX_SUBAGENTS) if options else MAX_SOURCES_PER_SUBAGENT * MAX_SUBAGENTS
        target_report_kb = options.get("target_report_kb", TARGET_REPORT_SIZE_KB) if options else TARGET_REPORT_SIZE_KB
        start_time = time.time()
        max_duration = float(max_hours) * 3600.0
        try:
            with research_lock:
                research_tasks[task_id]["status"] = "deep_planning"
                research_tasks[task_id]["progress"] = 5
            master_plan = self._generate_master_plan(user_query, max_sources)
            with research_lock:
                research_tasks[task_id]["master_plan"] = master_plan
                research_tasks[task_id]["progress"] = 10
            specialties = master_plan.get(
                "specialties",
                [
                    "általános kutatás",
                    "technikai elemzés",
                    "történeti kontextus",
                    "statisztikai adatok",
                    "szakértői vélemények",
                    "jövőbeli trendek",
                    "kapcsolódó területek",
                    "ellentétes nézetek",
                    "esettanulmányok",
                    "implementációs részletek",
                    "piaci elemzés",
                    "technológiai áttekintés",
                ],
            )
            if not isinstance(specialties, list) or not specialties:
                specialties = [
                    "általános kutatás",
                    "technikai elemzés",
                    "történeti kontextus",
                    "statisztikai adatok",
                ]
            all_iterations_data: List[Dict[str, Any]] = []
            iteration = 0
            while iteration < DEEP_RESEARCH_ITERATIONS:
                iteration += 1
                with research_lock:
                    research_tasks[task_id]["status"] = f"iteration_{iteration}_research"
                    research_tasks[task_id]["current_iteration"] = iteration
                num_subagents = min(len(specialties), MAX_SUBAGENTS)
                subagent_models = [self.grok_fast, self.gpt_oss, self.kimi, self.glm]
                subagents: List[SubAgent] = []
                for i in range(num_subagents):
                    agent_id = f"subagent_{i + 1}_iter{iteration}"
                    specialty = specialties[i % len(specialties)]
                    model = subagent_models[i % len(subagent_models)]
                    subagent = SubAgent(agent_id, specialty, model, self.exa)
                    subagents.append(subagent)
                total_slots = max(num_subagents * DEEP_RESEARCH_ITERATIONS, 1)
                sources_per_agent = max(int(max_sources // total_slots), 1)
                agent_results: List[Dict[str, Any]] = []
                with concurrent.futures.ThreadPoolExecutor(max_workers=num_subagents) as executor:
                    futures: Dict[concurrent.futures.Future, int] = {}
                    for idx, subagent in enumerate(subagents):
                        task_desc = master_plan.get("tasks", {}).get(subagent.specialty, user_query)
                        future = executor.submit(subagent.research, task_desc, sources_per_agent)
                        futures[future] = idx
                    for future in concurrent.futures.as_completed(futures):
                        try:
                            result = future.result()
                            agent_results.append(result)
                        except Exception as e:
                            logger.error(f"Subagent error: {e}")
                with research_lock:
                    research_tasks[task_id]["status"] = f"iteration_{iteration}_synthesis"
                synthesis = self._synthesize_with_middle_agent(user_query, agent_results)
                all_iterations_data.append(
                    {
                        "iteration": iteration,
                        "agent_results": agent_results,
                        "synthesis": synthesis,
                    }
                )
                total_sources_progress = 0
                for d in all_iterations_data:
                    for r in d["agent_results"]:
                        total_sources_progress += r.get("sources_count", 0)
                progress = 10 + int((iteration / DEEP_RESEARCH_ITERATIONS) * 80)
                with research_lock:
                    research_tasks[task_id]["progress"] = progress
                    research_tasks[task_id]["total_sources"] = total_sources_progress
                elapsed = time.time() - start_time
                if elapsed > max_duration:
                    logger.warning("Time limit reached, stopping research loop")
                    break
            with research_lock:
                research_tasks[task_id]["status"] = "finalizing"
                research_tasks[task_id]["progress"] = 90
            final_report = self._generate_final_report_multi_cycle(
                user_query,
                all_iterations_data,
                master_plan,
                target_report_kb,
            )
            final_size_kb = len(final_report.encode("utf-8")) / 1024.0
            elapsed_hours = (time.time() - start_time) / 3600.0
            total_sources = 0
            for d in all_iterations_data:
                for r in d["agent_results"]:
                    total_sources += r.get("sources_count", 0)
            with research_lock:
                research_tasks[task_id]["status"] = "completed"
                research_tasks[task_id]["progress"] = 100
                research_tasks[task_id]["report"] = final_report
                research_tasks[task_id]["final_report_size_kb"] = final_size_kb
                research_tasks[task_id]["elapsed_hours"] = elapsed_hours
            return {
                "success": True,
                "total_sources": total_sources,
                "iterations": len(all_iterations_data),
                "report_size_kb": final_size_kb,
                "elapsed_hours": elapsed_hours,
                "report": final_report,
            }
        except Exception as e:
            logger.error(f"Deep research error for task {task_id}: {str(e)}", exc_info=True)
            with research_lock:
                if task_id in research_tasks:
                    research_tasks[task_id]["status"] = "error"
                    research_tasks[task_id]["error"] = str(e)
            return {"success": False, "error": str(e)}

    def _generate_master_plan(self, query: str, max_sources: int) -> Dict[str, Any]:
        system_prompt = (
            "Te Grok-4-0709 vagy, a főagent. Készíts részletes, többrétegű kutatási tervet.\n"
            "Határozd meg:\n"
            "1. A fő kutatási területeket (specialties) - legalább 10-12 különböző terület\n"
            "2. Mindegyik területhez specifikus kutatási feladatokat\n"
            "3. A kutatás fókuszpontjait\n"
            "4. Az elvárható eredményeket\n\n"
            "Tilos mock, placeholder vagy kitalált adatokat használni.\n"
            "Válaszolj tisztán JSON formátumban, semmi más szöveg."
        )
        user_prompt = (
            "Kutatási téma: "
            + query
            + "\n\nMaximális források száma: "
            + str(max_sources)
            + "\n\nKészíts átfogó kutatási tervet JSON formátumban:\n"
            '{"specialties": ["terület1", "terület2", ...],'
            '"tasks": {"terület1": "kutatási feladat leírása", ...},'
            '"focus_points": ["fókusz1", "fókusz2", ...],'
            '"expected_outcomes": ["eredmény1", "eredmény2", ...]}'
        )
        response = self.main_grok.chat(
            [
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": user_prompt},
            ],
            temperature=0.3,
            max_tokens=min(XAI_MAX_TOKENS, 256000),
        )
        return self._extract_json(response["choices"][0]["message"]["content"])

    def _synthesize_with_middle_agent(self, query: str, agent_results: List[Dict[str, Any]]) -> str:
        synthesis_text_parts: List[str] = []
        synthesis_text_parts.append("# Kutatási téma: " + query + "\n")
        synthesis_text_parts.append("## Subagent eredmények:\n")
        for result in agent_results:
            specialty = result.get("specialty", "")
            sources_count = result.get("sources_count", 0)
            contents = result.get("contents", [])[:100]
            synthesis_text_parts.append("### " + specialty + " (Források: " + str(sources_count) + ")\n")
            for c in contents[:20]:
                title = c.get("title", "N/A")
                text = c.get("text", "")
                snippet = text[:500]
                synthesis_text_parts.append("- " + title + ": " + snippet + "...\n")
            synthesis_text_parts.append("\n")
        synthesis_text = "\n".join(synthesis_text_parts)
        system_prompt = (
            "Te Grok-4-fast-reasoning vagy, a middle agent.\n"
            "Szintetizálj átfogó összefoglalót a subagent-ek jelentéseiből.\n"
            "Tilos mock, placeholder vagy kitalált adatokat használni.\n"
            "Csak a valós forrásokból származó információkat használd."
        )
        user_prompt = (
            "Szintetizálj részletes összefoglalót az alábbi kutatási eredményekből:\n\n"
            + synthesis_text[:30000]
            + "\n\nKészíts strukturált, markdown formátumú összefoglalót."
        )
        try:
            response = self.middle_grok.chat(
                [
                    {"role": "system", "content": system_prompt},
                    {"role": "user", "content": user_prompt},
                ],
                temperature=0.3,
                max_tokens=min(XAI_MAX_TOKENS, 2000000),
            )
            return response["choices"][0]["message"]["content"]
        except Exception as e:
            logger.error(f"Middle agent synthesis error: {e}")
            return ""

    def _generate_final_report_multi_cycle(
        self,
        query: str,
        all_iterations_data: List[Dict[str, Any]],
        master_plan: Dict[str, Any],
        target_kb: int,
    ) -> str:
        synthesis_sections: List[str] = []
        for d in all_iterations_data:
            iteration = d.get("iteration", 0)
            synthesis = d.get("synthesis", "")
            synthesis_sections.append("# Iteráció " + str(iteration) + "\n\n" + synthesis)
        all_synthesis = "\n\n---\n\n".join(synthesis_sections)
        target_bytes = int(target_kb) * 1024
        max_out_tokens = int(CEREBRAS_MAX_TOKENS)
        if max_out_tokens <= 0:
            max_out_tokens = 40000
        estimated_cycles = max(1, int(target_bytes / float(max_out_tokens * 4)))
        logger.info(f"GPT-OSS final report generation in {estimated_cycles} cycles")
        report_sections: List[str] = []
        for cycle in range(1, estimated_cycles + 1):
            logger.info(f"GPT-OSS cycle {cycle}/{estimated_cycles}")
            system_prompt = (
                "Te GPT-OSS-120B vagy, a végső jelentés írója.\n"
                "Ciklus "
                + str(cycle)
                + "/"
                + str(estimated_cycles)
                + " - Készíts részletes, szakmai jelentést.\n"
                "Tilos mock, placeholder vagy kitalált adatokat használni.\n"
                "Csak a valós kutatási eredményeket használd."
            )
            if cycle == 1:
                section_title = "Bevezető és kontextus"
            else:
                section_title = "Részletes elemzés " + str(cycle) + ". rész"
            master_plan_str = json.dumps(master_plan, indent=2, ensure_ascii=False)
            master_plan_str = master_plan_str[:2000]
            synthesis_slice = all_synthesis[:25000]
            user_prompt = (
                "Kutatási téma: "
                + query
                + "\n\nCiklus "
                + str(cycle)
                + "/"
                + str(estimated_cycles)
                + " - "
                + section_title
                + "\n\nMaster terv:\n"
                + master_plan_str
                + "\n\nKutatási eredmények:\n"
                + synthesis_slice
                + "\n\nÍrj részletes, strukturált jelentést markdown formátumban.\nMinimum 2000 szó, maximum részletességgel."
            )
            try:
                response = self.gpt_oss.chat(
                    [
                        {"role": "system", "content": system_prompt},
                        {"role": "user", "content": user_prompt},
                    ],
                    temperature=0.5,
                    max_tokens=max_out_tokens,
                )
                section = response["choices"][0]["message"]["content"]
                report_sections.append(section)
                current_size = sum(len(s.encode("utf-8")) for s in report_sections)
                logger.info(f"Cycle {cycle} done, current size: {current_size / 1024.0:.1f} KB")
                if current_size >= target_bytes * 0.95:
                    logger.info("Target size reached, stopping final report generation")
                    break
            except Exception as e:
                logger.error(f"GPT-OSS cycle {cycle} error: {e}")
                break
        total_sources = 0
        for iteration_data in all_iterations_data:
            for result in iteration_data["agent_results"]:
                total_sources += result.get("sources_count", 0)
        header_lines: List[str] = []
        header_lines.append("# " + query + "\n")
        header_lines.append("## Kutatási Metaadatok\n")
        header_lines.append("- Témakör: " + query)
        header_lines.append("- Összes feldolgozott forrás: " + f"{total_sources:,}")
        header_lines.append("- Iterációk száma: " + str(len(all_iterations_data)))
        header_lines.append("- Generálási időpont: " + datetime.now().strftime("%Y-%m-%d %H:%M:%S"))
        header_lines.append("- Generálási ciklusok: " + str(len(report_sections)))
        header_lines.append("---\n")
        header = "\n".join(header_lines) + "\n\n"
        references_lines: List[str] = []
        references_lines.append("## Források és Hivatkozások\n")
        ref_num = 1
        for iteration_data in all_iterations_data:
            for result in iteration_data["agent_results"]:
                for source in result.get("sources", [])[:30]:
                    title = source.get("title", "N/A")
                    url = source.get("url", "N/A")
                    references_lines.append("[" + str(ref_num) + "] " + title + " - " + url)
                    ref_num += 1
                    if ref_num > 500:
                        break
                if ref_num > 500:
                    break
            if ref_num > 500:
                break
        references = "\n".join(references_lines)
        final_report = header + "\n\n".join(report_sections) + "\n\n" + references
        return final_report

    def _extract_json(self, text: str) -> Dict[str, Any]:
        text = (text or "").strip()
        try:
            return json.loads(text)
        except json.JSONDecodeError:
            pass
        json_match = re.search(r"``````", text, re.DOTALL)
        if json_match:
            try:
                return json.loads(json_match.group(1))
            except Exception:
                pass
        brace_count = 0
        start = -1
        for i, ch in enumerate(text):
            if ch == "{":
                if brace_count == 0:
                    start = i
                brace_count += 1
            elif ch == "}":
                brace_count -= 1
                if brace_count == 0 and start != -1:
                    try:
                        return json.loads(text[start : i + 1])
                    except Exception:
                        start = -1
        return {}


